template <typename Derived>
struct StaticBase {
    // Optimization: Elimination of vtable lookup
    void interface_op() const {
        // Static dispatch via CRTP
        static_cast<const Derived*>(this)->execute();
    }
};

struct ImplementationA : StaticBase<ImplementationA> {
    void execute() const {
        // Implementation A code
    }
};

struct ImplementationB : StaticBase<ImplementationB> {
    void execute() const {
        // Implementation B code
    }
};

void usage(ImplementationA a) {
    // Calls execute() directly at compile time
    a.interface_op();
}
